changeSet.sql:
-- L'agent : sa tournee, et ses passages. Rien d'autre. INSERT INTO authoritypermission (authorityid, permission) SELECT authorityid, p FROM authority, (VALUES ('VIEW_COLLECTION_ROUTE'), ('DECLARE_COLLECTION')) AS perms(p) WHERE name = 'AGENT';
-- L'administration exerce les memes actes, plus les siens. Elle n'est pas bornee a un -- territoire (TerritorialAccessGuard), mais elle a bien besoin du droit d'agir. INSERT INTO authoritypermission (authorityid, permission) SELECT authorityid, p FROM authority, (VALUES ('VIEW_COLLECTION_ROUTE'), ('DECLARE_COLLECTION'), ('VIEW_SUPERVISION'), ('MANAGE_DEVICES'), ('SEND_AWARENESS')) AS perms(p) WHERE name IN ('ADMIN', 'SUPER_ADMIN');
-- ACCESS_MY_ACTIVITIES ne decrivait rien : l'agent ne la porte plus. DELETE FROM authoritypermission WHERE permission = 'ACCESS_MY_ACTIVITIES' AND authorityid = (SELECT authorityid FROM authority WHERE name = 'AGENT');

changeSet.rollback:
DELETE FROM authoritypermission WHERE permission IN
    ('VIEW_COLLECTION_ROUTE','DECLARE_COLLECTION','VIEW_SUPERVISION',
     'MANAGE_DEVICES','SEND_AWARENESS');
INSERT INTO authoritypermission (authorityid, permission)
SELECT authorityid, 'ACCESS_MY_ACTIVITIES' FROM authority WHERE name = 'AGENT';
